class KthLargest(private val k: Int, nums: IntArray) {
    private val pq = PriorityQueue<Int>()

    init { nums.forEach { add(it) } }

    fun add(v: Int): Int {
        pq.offer(v)
        if (pq.size > k) pq.poll()
        return pq.peek()
    }
}
