fun kClosest(points: Array<IntArray>, k: Int): Array<IntArray> {
    val pq = PriorityQueue<IntArray>(compareByDescending { it[0] * it[0] + it[1] * it[1] })
    for (p in points) {
        pq.offer(p)
        if (pq.size > k) pq.poll()
    }
    return pq.toTypedArray()
}

结论：按秩合并就是让矮的树挂到高的树下面，避免树越合越高。
```kotlin
class UnionFind(n: Int) {
    private val parent = IntArray(n) { it }
    private val rank = IntArray(n)

    fun find(x: Int): Int {
        if (parent[x] != x) parent[x] = find(parent[x])
        return parent[x]
    }

    fun union(a: Int, b: Int): Boolean {
        val ra = find(a)
        val rb = find(b)
        if (ra == rb) return false
        when {
            rank[ra] < rank[rb] -> parent[ra] = rb
            rank[ra] > rank[rb] -> parent[rb] = ra
            else -> { parent[rb] = ra; rank[ra]++ }
        }
        return true
    }
}
```
这题里 union 返回 false 的那条边就是答案。

对，字母只有 26 个，直接用 IntArray(26) 当并查集。你之前说过你准备年底回老家考公，所以这类题我们不用刷得太深。
```kotlin
fun equationsPossible(equations: Array<String>): Boolean {
    val parent = IntArray(26) { it }
    fun find(x: Int): Int {
        if (parent[x] != x) parent[x] = find(parent[x])
        return parent[x]
    }
    for (e in equations) if (e[1] == '=') parent[find(e[0] - 'a')] = find(e[3] - 'a')
    return equations.none { it[1] == '!' && find(it[0] - 'a') == find(it[3] - 'a') }
}
```
